screenPanels.initJs:
function(container, apiUrl, tables) {
  const ticketTableIdx = 0;
  const impactTableIdx = 1;
  const assetTableIdx = 2;
  const auditLogTableIdx = 3;

  let currentTicketId = null;
  let allTickets = [];
  let allAssets = [];
  let allLogs = [];

  // ========== UI 要素の取得 ==========
  const ticketTbody = container.querySelector('#ticket-tbody');
  const createBtn = container.querySelector('[data-testid="create-ticket-btn"]');
  const createModal = container.querySelector('#create-modal');
  const statusConfirmModal = container.querySelector('#status-confirm-modal');
  const saveTicketBtn = container.querySelector('[data-testid="save-ticket-btn"]');
  const backDashboardBtn = container.querySelector('[data-testid="back-to-dashboard-btn"]');
  const tabButtons = container.querySelectorAll('.tab-btn');
  const tabContents = container.querySelectorAll('.tab-content');
  const closeModalBtns = container.querySelectorAll('.close-modal');

  // ========== イベントリスナー ==========
  createBtn.addEventListener('click', () => {
    createModal.style.display = 'flex';
  });

  closeModalBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.target.closest('.modal-overlay').style.display = 'none';
    });
  });

  createModal.addEventListener('click', (e) => {
    if (e.target === createModal) createModal.style.display = 'none';
  });

  statusConfirmModal.addEventListener('click', (e) => {
    if (e.target === statusConfirmModal) statusConfirmModal.style.display = 'none';
  });

  // タブ切り替え
  tabButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      const tabName = btn.dataset.tab;
      tabButtons.forEach(b => {
        b.style.color = 'var(--text-muted)';
        b.style.borderBottomColor = 'transparent';
      });
      btn.style.color = 'var(--text)';
      btn.style.borderBottomColor = 'var(--primary)';
      tabContents.forEach(content => content.style.display = 'none');
      container.querySelector(`#tab-${tabName}`).style.display = 'block';
    });
  });

  // チケット一覧行クリック
  ticketTbody.addEventListener('click', (e) => {
    const row = e.target.closest('tr');
    if (row) {
      currentTicketId = row.dataset.id;
      loadTicketDetail(currentTicketId);
    }
  });

  // ステータス変更確認
  const statusSelect = container.querySelector('[data-testid="status-select"]');
  let pendingStatus = null;
  statusSelect.addEventListener('change', (e) => {
    if (e.target.value) {
      pendingStatus = e.target.value;
      container.querySelector('#status-confirm-msg').textContent = `ステータスを「${e.target.value}」に変更してもよろしいですか？`;
      statusConfirmModal.style.display = 'flex';
    }
  });

  container.querySelector('[data-testid="confirm-status-btn"]').addEventListener('click', () => {
    statusSelect.value = pendingStatus;
    statusConfirmModal.style.display = 'none';
    addHistoryEntry(pendingStatus);
  });

  // 保存ボタン
  saveTicketBtn.addEventListener('click', async () => {
    const ticketData = {
      id: currentTicketId,
      title: container.querySelector('[data-testid="ticket-title"]').value,
      description: container.querySelector('[data-testid="ticket-description"]').value,
      status: container.querySelector('[data-testid="status-select"]').value,
      priority: container.querySelector('[data-testid="priority-select"]').value,
      assignee: container.querySelector('[data-testid="assignee-select"]').value,
      dueDate: container.querySelector('[data-testid="due-date"]').value,
    };
    const updated = await window.aivicApi.update(ticketTableIdx, currentTicketId, ticketData);
    if (updated) {
      loadTicketList();
      loadTicketDetail(currentTicketId);
    }
  });

  // 新規チケット作成
  container.querySelector('[data-testid="modal-create-btn"]').addEventListener('click', async () => {
    const vulnId = container.querySelector('[data-testid="modal-vuln-select"]').value;
    const title = container.querySelector('[data-testid="modal-title"]').value;
    const priority = container.querySelector('[data-testid="modal-priority"]').value;
    if (!vulnId || !title || !priority) {
      alert('すべてのフィールドを入力してください');
      return;
    }
    const newTicket = {
      vulnerabilityId: vulnId,
      title: title,
      status: '未対応',
      priority: priority,
      assignee: '',
      dueDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    };
    const saved = await window.aivicApi.save(ticketTableIdx, newTicket);
    if (saved) {
      createModal.style.display = 'none';
      loadTicketList();
    }
  });

  // ダッシュボード戻る
  backDashboardBtn.addEventListener('click', () => {
    window.showScreen('scr-1788230867652');
  });

  // ========== データ読み込み ==========
  async function loadTicketList() {
    allTickets = await window.aivicApi.list(ticketTableIdx) || [];
    ticketTbody.innerHTML = '';
    allTickets.forEach(ticket => {
      const row = document.createElement('tr');
      row.dataset.id = ticket.id;
      row.style.borderBottom = '1px solid var(--border)';
      row.style.cursor = 'pointer';
      row.style.transition = 'background 200ms';
      row.addEventListener('mouseenter', () => row.style.background = 'var(--bg-main)');
      row.addEventListener('mouseleave', () => row.style.background = 'transparent');
      row.innerHTML = `
        <td style="padding: 8px 12px; font-size: 11px; color: var(--text-muted);">${ticket.id ? ticket.id.substring(0, 8) : '-'}</td>
        <td style="padding: 8px 12px; font-size: 12px; color: var(--text);">${ticket.title || '-'}</td>
        <td style="padding: 8px 12px; font-size: 11px;"><span style="background: var(--bg-main); padding: 2px 6px; border-radius: 3px; color: var(--text);">${ticket.status || '-'}</span></td>
        <td style="padding: 8px 12px; font-size: 11px; color: var(--text);">${ticket.priority || '-'}</td>
        <td style="padding: 8px 12px; font-size: 11px; color: var(--text-muted);">${ticket.assignee || '-'}</td>
        <td style="padding: 8px 12px; font-size: 11px; color: var(--text-muted);">${ticket.dueDate ? ticket.dueDate.substring(0, 10) : '-'}</td>
        <td style="padding: 8px 12px; font-size: 11px; text-align: center; color: var(--primary);">0%</td>
      `;
      ticketTbody.appendChild(row);
    });
  }

  async function loadTicketDetail(ticketId) {
    const ticket = allTickets.find(t => t.id === ticketId);
    if (!ticket) return;

    container.querySelector('[data-testid="ticket-id"]').value = ticket.id || '';
    container.querySelector('[data-testid="vuln-id"]').value = ticket.vulnerabilityId || '';
    container.querySelector('[data-testid="cve-id"]').value = ticket.cveId || '';
    container.querySelector('[data-testid="cvss-score"]').value = ticket.cvssScore || '';
    container.querySelector('[data-testid="detected-date"]').value = ticket.detectedDate ? ticket.detectedDate.substring(0, 10) : '';
    container.querySelector('[data-testid="due-date"]').value = ticket.dueDate || '';
    container.querySelector('[data-testid="ticket-title"]').value = ticket.title || '';
    container.querySelector('[data-testid="ticket-description"]').value = ticket.description || '';
    container.querySelector('[data-testid="status-select"]').value = ticket.status || '';
    container.querySelector('[data-testid="priority-select"]').value = ticket.priority || '';
    container.querySelector('[data-testid="assignee-select"]').value = ticket.assignee || '';

    // 影響範囲
    const impact = await window.aivicApi.list(impactTableIdx) || [];
    const ticketImpact = impact.find(i => i.ticketId === ticketId);
    if (ticketImpact) {
      container.querySelector('#impact-users').textContent = ticketImpact.affectedUsers || '-';
      container.querySelector('#impact-systems').textContent = ticketImpact.affectedSystems || '-';
      container.querySelector('#impact-level').textContent = ticketImpact.impactLevel || '-';
      container.querySelector('#impact-priority').textContent = ticketImpact.responsePriority || '-';
    }

    // システム資産
    allAssets = await window.aivicApi.list(assetTableIdx) || [];
    const assetsTbody = container.querySelector('#assets-tbody');
    assetsTbody.innerHTML = '';
    allAssets.slice(0, 10).forEach(asset => {
      const row = document.createElement('tr');
      row.style.borderBottom = '1px solid var(--border)';
      row.innerHTML = `
        <td style="padding: 6px 8px; font-size: 11px; color: var(--text);">${asset.name || '-'}</td>
        <td style="padding: 6px 8px; font-size: 11px; color: var(--text-muted);">${asset.type || '-'}</td>
        <td style="padding: 6px 8px; font-size: 11px; color: var(--text);">${asset.importance || '-'}</td>
        <td style="padding: 6px 8px; font-size: 11px; color: var(--text);">${asset.status || '-'}</td>
      `;
      assetsTbody.appendChild(row);
    });

    // 監査ログ
    allLogs = await window.aivicApi.list(auditLogTableIdx) || [];
    loadAuditLogs();

    // 履歴タイムライン
    loadHistoryTimeline(ticketId);
  }

  function loadHistoryTimeline(ticketId) {
    const timeline = container.querySelector('#history-timeline');
    timeline.innerHTML = '';
    const historyEntries = [
      { date: new Date().toISOString(), status: '未対応', user: 'システム', comment: 'チケット作成' },
    ];
    historyEntries.forEach((entry, idx) => {
      const item = document.createElement('div');
      item.style.marginBottom = '16px';
      item.style.position = 'relative';
      item.innerHTML = `
        <div style="position: absolute; left: -16px; top: 2px; width: 8px; height: 8px; background: var(--primary); border-radius: 50%; border: 2px solid var(--bg-card);"></div>
        <div style="font-size: 11px; color: var(--text-muted);">${new Date(entry.date).toLocaleString('ja-JP')}</div>
        <div style="font-size: 12px; color: var(--text); font-weight: 500; margin-top: 2px;">ステータス: ${entry.status}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${entry.user} - ${entry.comment}</div>
      `;
      timeline.appendChild(item);
    });
  }

  function addHistoryEntry(status) {
    const timeline = container.querySelector('#history-timeline');
    const item = document.createElement('div');
    item.style.marginBottom = '16px';
    item.style.position = 'relative';
    item.innerHTML = `
      <div style="position: absolute; left: -16px; top: 2px; width: 8px; height: 8px; background: var(--primary); border-radius: 50%; border: 2px solid var(--bg-card);"></div>
      <div style="font-size: 11px; color: var(--text-muted);">${new Date().toLocaleString('ja-JP')}</div>
      <div style="font-size: 12px; color: var(--text); font-weight: 500; margin-top: 2px;">ステータス: ${status}</div>
      <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">現在のユーザー - ステータス更新</div>
    `;
    timeline.insertBefore(item, timeline.firstChild);
  }

  function loadAuditLogs() {
    const logsTbody = container.querySelector('#logs-tbody');
    logsTbody.innerHTML = '';
    allLogs.slice(0, 10).forEach(log => {
      const row = document.createElement('tr');
      row.style.borderBottom = '1px solid var(--border)';
      row.innerHTML = `
        <td style="padding: 6px 8px; font-size: 10px; color: var(--text-muted);">${log.timestamp ? new Date(log.timestamp).toLocaleString('ja-JP') : '-'}</td>
        <td style="padding: 6px 8px; font-size: 11px; color: var(--text);">${log.eventType || '-'}</td>
        <td style="padding: 6px 8px; font-size: 11px; color: var(--text);">${log.user || '-'}</td>
        <td style="padding: 6px 8px; font-size: 11px; color: var(--text-muted);">${log.resource || '-'}</td>
        <td style="padding: 6px 8px; font-size: 11px; color: var(--text);">${log.result || '-'}</td>
      `;
      logsTbody.appendChild(row);
    });
  }

  // ログフィルタ
  container.querySelector('[data-testid="filter-logs-btn"]').addEventListener('click', () => {
    loadAuditLogs();
  });

  // 初期化
  loadTicketList();
  if (tabButtons.length > 0) {
    tabButtons[0].click();
  }
}
